  2→  AC: @ui-task-board ac-4 — Active Fleet row showing running agent work.
  3→  Shows task title, agent name, elapsed time with pulse indicator,
  4→  and last few lines of output.
  5→-->
  6→<script lang="ts">
  7→	import type { AgentStatus } from '$lib/api';
  8→	import { Badge } from '$lib/components/ui/badge';
  9→	import { formatElapsed } from './board-utils';
 10→	import Bot from '@lucide/svelte/icons/bot';
 11→	import Activity from '@lucide/svelte/icons/activity';
 12→	import Terminal from '@lucide/svelte/icons/terminal';
 13→
 14→	let {
 15→		status,
 16→		outputLines = {},
 17→		taskTitles = {}
 18→	}: {
 19→		status: AgentStatus | null;
 20→		outputLines?: Record<string, string[]>;
 21→		taskTitles?: Record<string, string>;
 22→	} = $props();
 23→
 24→	let activeInvocations = $derived(status?.active_invocations ?? []);
 25→	let isVisible = $derived(status?.dispatch_enabled && activeInvocations.length > 0);
 26→</script>
 27→
 28→{#if isVisible}
 29→	<div class="mb-4" data-testid="active-fleet-row">
 30→		<div class="flex items-center gap-2 mb-2">
 31→			<Activity class="size-4 text-status-in-progress" />
 32→			<h3 class="text-sm font-medium">Active Fleet</h3>
 33→			<Badge variant="secondary" class="text-[10px]">{activeInvocations.length} running</Badge>
 34→		</div>
 35→		<div class="flex gap-3 overflow-x-auto pb-2">
 36→			{#each activeInvocations as invocation (invocation.session_id)}
 37→				{@const lines = outputLines[invocation.session_id] ?? []}
 38→				{@const title = invocation.task_ref ? taskTitles[invocation.task_ref] : undefined}
 39→				<div
 40→					class="flex-shrink-0 w-72 rounded-lg border bg-card p-3 ds-breathe"
 41→					data-testid="fleet-card"
 42→				>
 43→					<div class="flex items-center gap-2 mb-1.5">
 44→						<Bot class="size-4 text-muted-foreground" />
 45→						<span class="text-xs font-medium truncate">{invocation.agent_id}</span>
 46→					</div>
 47→
 48→					{#if invocation.task_ref}
 49→						{#if title}
 50→							<p class="text-xs text-foreground truncate mb-0.5" data-testid="fleet-task-title">
 51→								{title}
 52→							</p>
 53→							<p class="text-[10px] text-muted-foreground font-mono truncate mb-1">
 54→								{invocation.task_ref}
 55→							</p>
 56→						{:else}
 57→							<p class="text-xs text-muted-foreground font-mono truncate mb-1">
 58→								{invocation.task_ref}
 59→							</p>
 60→						{/if}
 61→					{/if}
 62→
 63→					<div class="flex items-center gap-1.5 text-[10px] text-muted-foreground mb-1.5">
 64→						<!-- Pulse indicator -->
 65→						<span class="relative flex size-2">
 66→							<span
 67→								class="absolute inline-flex h-full w-full rounded-full bg-status-in-progress opacity-75 ds-breathe"
 68→							></span>
 69→							<span class="relative inline-flex size-2 rounded-full bg-status-in-progress"></span>
 70→						</span>
 71→						<span>{formatElapsed(invocation.elapsed_ms)}</span>
 72→					</div>
 73→
 74→					<!-- AC: @ui-task-board ac-4 — Last few lines of output -->
 75→					{#if lines.length > 0}
 76→						<div
 77→							class="mt-1.5 rounded bg-muted/50 p-1.5 font-mono text-[10px] leading-tight text-muted-foreground overflow-hidden max-h-14"
 78→							aria-live="polite"
 79→							aria-label="Agent output for {title ?? invocation.agent_id}"
 80→							data-testid="fleet-output"
 81→						>
 82→							{#each lines as line}
 83→								<div class="truncate">{line}</div>
 84→							{/each}
 85→						</div>
 86→					{:else}
 87→						<div
 88→							class="mt-1.5 flex items-center gap-1 text-[10px] text-muted-foreground/50"
 89→							aria-live="polite"
 90→							aria-label="Agent output for {title ?? invocation.agent_id}"
 91→							data-testid="fleet-output-empty"
 92→						>
 93→							<Terminal class="size-3" />
 94→							<span>Awaiting output...</span>
 95→						</div>
 96→					{/if}
 97→				</div>
 98→			{/each}
 99→		</div>
100→	</div>
101→{/if}
