import { z } from "zod";
import {
  DateTimeSchema,
  RefSchema,
  SlugSchema,
  TaskStatusSchema,
  TaskTypeSchema,
  UlidSchema,
  VcsRefSchema,
} from "./common.js";

/**
 * Automation eligibility status for tasks
 * AC: @task-automation-eligibility ac-1
 * - eligible: Task can be processed by automation loops
 * - needs_review: Task was rejected by automation and needs human review
 * - manual_only: Task should only be handled by humans
 * - undefined/absent: Task has not been assessed for automation (unassessed)
 */
export const AutomationStatusSchema = z.enum([
  "eligible",
  "needs_review",
  "manual_only",
]);

/**
 * Note entry - append-only work log
 */
export const NoteSchema = z.object({
  _ulid: UlidSchema,
  created_at: DateTimeSchema,
  author: z.string().optional(),
  content: z.string(),
  supersedes: UlidSchema.nullable().optional(),
});

/**
 * Todo item - lightweight checklist
 */
export const TodoSchema = z.object({
  id: z.number().int().positive(),
  text: z.string(),
  done: z.boolean().default(false),
  done_at: DateTimeSchema.optional(),
  added_at: DateTimeSchema,
  added_by: z.string().optional(),
  promoted_to: RefSchema.optional(),
});

/**
 * Full task schema
 * Note: created_at defaults to now if not provided (auto-populated on load)
 */
export const TaskSchema = z.object({
  // Identity
  _ulid: UlidSchema,
  slugs: z.array(SlugSchema).default([]),
  title: z.string().min(1, "Title is required"),
  type: TaskTypeSchema.default("task"),

/**
 * API Response Types
 *
 * Shared types for REST API responses between daemon and web-ui.
 * These types define the contract for HTTP endpoints.
 */
/**
 * Common paginated response wrapper
 * AC: @api-contract ac-4
 */
export interface PaginatedResponse<T> {
    items: T[];
    total: number;
    offset: number;
    limit: number;
}
/**
 * Standard error response
 * AC: @api-contract ac-22, ac-23, ac-24
 */
export interface ErrorResponse {
    error: string;
    message?: string;
    suggestion?: string;
    details?: Array<{
        field: string;
        message: string;
    }>;
    current?: string;
    valid_transitions?: string[];
}
/**
 * Task summary for list endpoints
 * AC: @api-contract ac-2
 */
export interface TaskSummary {
    _ulid: string;
    slugs: string[];
    title: string;
    type: string;
    status: string;
    priority: number;
    spec_ref?: string;
    tags: string[];
    depends_on: string[];
    automation?: string;
    created_at: string;
    started_at?: string;
    notes_count: number;
    todos_count?: number;
}
/**
 * Full task with notes and todos
 * AC: @api-contract ac-5
 */
export interface TaskDetail extends TaskSummary {
    derivation?: string;
    blocked_by: string[];
    depends_on: string[];
    context: string[];
    vcs_refs: string[];
    notes: Note[];
    todos?: Todo[];
}
/**
 * Task note
 */
export interface Note {
    _ulid: string;
    created_at: string;
    author: string;
    content: string;
    supersedes?: string;
}
/**
 * Task todo
 */
export interface Todo {
    _ulid: string;
    content: string;
    status: 'pending' | 'in_progress' | 'completed';
    created_at: string;
}
/**
 * Spec item summary for list endpoints
 * AC: @api-contract ac-8
 */
export interface ItemSummary {
    _ulid: string;
    slugs: string[];
    title: string;
    type: string;
    status?: string;
    tags: string[];
    parent?: string;
    created_at: string;
}
/**
 * Full spec item with ACs and traits
 * AC: @api-contract ac-10
 */
export interface ItemDetail extends ItemSummary {
    description?: string;
    acceptance_criteria: AcceptanceCriterion[];
    traits: string[];
    depends_on: string[];
    priority?: number;
}
/**
 * Acceptance criterion
 */
export interface AcceptanceCriterion {
    _ulid: string;
    given: string;
    when: string;
    then: string;
    /** Test coverage status: true=covered, false=not covered, undefined=unknown */
    covered?: boolean;
}
/**
 * Inbox item
 * AC: @api-contract ac-12
 */
export interface InboxItem {
    _ulid: string;
    text: string;
    tags: string[];
    added_by: string;
    created_at: string;
}
/**
 * Session context
 * AC: @api-contract ac-15
 */
export interface SessionContext {
    focus?: string;
    threads: string[];
    open_questions: string[];
    updated_at: string;
}
/**
 * Agent definition
 * AC: @api-contract ac-16
 */
export interface Agent {
    _ulid: string;
    slugs: string[];
    role: string;
    status: string;
    capabilities: string[];
    constraints: string[];
}
/**
 * Workflow definition
 * AC: @api-contract ac-17
 */
export interface Workflow {
    _ulid: string;
    slugs: string[];
    name: string;
    steps: WorkflowStep[];
}
/**
 * Workflow step
 */
export interface WorkflowStep {
    _ulid: string;
    type: 'action' | 'check' | 'decision';
    content: string;
}
/**
 * Observation
 * AC: @api-contract ac-18
 */
export interface Observation {
    _ulid: string;
    type: 'friction' | 'success' | 'question' | 'idea';
    content: string;
    context?: string;
    created_at: string;
    resolved?: boolean;
    resolution?: string;
}
/**
 * Plan summary for list endpoints
 * AC: @ui-plans-view ac-1
 */
export interface PlanSummary {
    _ulid: string;
    slugs: string[];
    title: string;
    status: string;
    created_at: string;
    approved_at?: string;
    completed_at?: string;
    derived_specs: string[];
    derived_tasks: string[];
    spec_count: number;
    task_count: number;
    task_progress: {
        total: number;
        completed: number;
        in_progress: number;
        pending: number;
        blocked: number;
    };
}
/**
 * Search result
 * AC: @api-contract ac-19
 * AC: @web-dashboard ac-24
 */
export interface SearchResult {
    type: 'item' | 'task' | 'inbox' | 'observation' | 'agent' | 'workflow' | 'convention';
    ulid: string;
    title: string;
    matchedFields: string[];
}
/**
 * Search response
 * AC: @api-contract ac-19
 * AC: @web-dashboard ac-24
 */
export interface SearchResponse {
    results: SearchResult[];
    total: number;
    showing: number;
}
/**
 * Validation result
 * AC: @api-contract ac-20
 */
export interface ValidationResult {
    valid: boolean;
    errors: ValidationError[];
    warnings: ValidationWarning[];
}
/**
 * Validation error
 */
export interface ValidationError {
    file: string;
    field: string;
    message: string;
    ref?: string;
}
/**
 * Validation warning
 */
export interface ValidationWarning {
    file: string;
    message: string;
    ref?: string;
}
/**
 * Alignment index stats
 * AC: @api-contract ac-21
 */
export interface AlignmentStats {
    total_specs: number;
    total_tasks: number;
    specs_without_tasks: number;
    tasks_without_specs: number;
    warnings: string[];
}
/**
 * Convention definition from meta manifest
 */
export interface Convention {
    _ulid: string;
    domain: string;
    rules: string[];
    examples?: Array<{
        good: string;
        bad: string;
    }>;
    validation?: {
        type: 'regex' | 'enum' | 'range' | 'prose';
        pattern?: string;
        message?: string;
        allowed?: string[];
        min?: number;
        max?: number;
        unit?: 'words' | 'chars' | 'lines';
    };
}
/**
 * Triage status lifecycle
 */
export type TriageStatus = 'pending' | 'triaged' | 'acted_on';
/**
 * Triage action types
 */
export type TriageAction = 'promote' | 'delete' | 'defer' | 'spec-gap' | 'duplicate';
/**
 * Triage record
 */
export interface TriageRecord {
    _ulid: string;
    inbox_ref: string;
    item_snapshot: string;
    status: TriageStatus;
    action?: TriageAction;
    reasoning?: string;
    decided_by?: string;
    evidence_refs: string[];
    override_reasoning?: string;
    override_by?: string;
    override_at?: string;
    acted_at?: string;
    result_ref?: string;
    created_at: string;
    updated_at?: string;
}
/**
 * Acceptance criterion with inheritance tracking
 */
export interface InheritedAC extends AcceptanceCriterion {
    _inherited_from: string;
}
/**
 * Exported task with resolved spec reference title
 */
export interface ExportedTask extends TaskDetail {
    spec_ref_title?: string;
}
/**
 * Exported spec item with nested hierarchy and inherited ACs.
 * Note: extends ItemDetail (acceptance_criteria required) because the JSON
 * snapshot always includes the field. The core export module uses Omit to
 * build from parser types where AC may not yet exist, but by the time data
 * reaches the web-ui via snapshot, AC is always present (at least as []).
 */
export interface ExportedItem extends ItemDetail {
    children?: ExportedItem[];
    inherited_acs?: InheritedAC[];
}
/**
 * Project metadata in a snapshot
 */
export interface ExportedProject {
    name: string;
    version?: string;
    description?: string;
}
/**
 * Validation result included in a snapshot
 */
export interface ExportedValidation {
    valid: boolean;
    errorCount: number;
    warningCount: number;
    errors: Array<{
        file: string;
        message: string;
        path?: string;
    }>;
    warnings: Array<{
        file: string;
        message: string;
    }>;
}
/**
 * Full kspec snapshot structure
 */
export interface KspecSnapshot {
    version: string;
    exported_at: string;
    project: ExportedProject;
    tasks: ExportedTask[];
    items: ExportedItem[];
    inbox: InboxItem[];
    session: SessionContext | null;
    observations: Observation[];
    agents: Agent[];
    workflows: Workflow[];
    conventions: Convention[];
    validation?: ExportedValidation;
}
