 38→		Object.fromEntries(
 39→			tasks.flatMap((t) => {
 40→				const entries: [string, string][] = [
 41→					[`@${t._ulid}`, t.title]
 42→				];
 43→				for (const slug of t.slugs) {
 44→					entries.push([`@${slug}`, t.title]);
 45→				}
 46→				return entries;
 47→			})
 48→		)
 49→	);
