 52→	let modalOpen = $state(false);
 53→	let selectedTaskRef = $state<string | null>(null);
 54→
 55→	// Track last processed URL ref to avoid infinite loops
 56→	let lastProcessedRef = $state('');
 57→
 58→	$effect(() => {
 59→		// Re-derive columns whenever tasks change
 60→		columns = distributeToColumns(tasks);
 61→	});
